48	  // Bit lengths beyond 2^53 are unreachable here, so split via division.
49	  const hi = Math.floor(bitLength / 0x100000000);
50	  const lo = bitLength >>> 0;
51	  const tail = padded.length - 8;
52	  padded[tail] = (hi >>> 24) & 0xff;
53	  padded[tail + 1] = (hi >>> 16) & 0xff;
54	  padded[tail + 2] = (hi >>> 8) & 0xff;
55	  padded[tail + 3] = hi & 0xff;
56	  padded[tail + 4] = (lo >>> 24) & 0xff;
57	  padded[tail + 5] = (lo >>> 16) & 0xff;
58	  padded[tail + 6] = (lo >>> 8) & 0xff;
