64	  for (let offset = 0; offset < padded.length; offset += SHA256_BLOCK_SIZE) {
65	    for (let t = 0; t < 16; t++) {
66	      const i = offset + t * 4;
67	      w[t] = ((padded[i] << 24) | (padded[i + 1] << 16) | (padded[i + 2] << 8) | padded[i + 3]) >>> 0;
68	    }
69	    for (let t = 16; t < 64; t++) {
70	      const w15 = w[t - 15];
71	      const w2 = w[t - 2];
72	      const s0 = (rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3)) >>> 0;
73	      const s1 = (rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10)) >>> 0;
74	      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
75	    }
