83	      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
84	      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
85	      const temp2 = (S0 + maj) >>> 0;
