7	/**
8	 * Derive the fixed-width HMAC key: keys longer than one block are hashed first,
9	 * shorter keys are zero-padded on the right.
10	 *
11	 * @param {Uint8Array} key
12	 * @returns {Uint8Array} exactly SHA256_BLOCK_SIZE bytes
13	 */
14	function normalizeKey(key) {
15	  const block = new Uint8Array(SHA256_BLOCK_SIZE);
16	  block.set(key.length > SHA256_BLOCK_SIZE ? sha256(key) : key, 0);
17	  return block;
18	}
