20	/**
21	 * @param {Uint8Array} key raw key octets (an empty key is valid)
22	 * @param {Uint8Array} message
23	 * @returns {Uint8Array} the 32-byte MAC
24	 */
25	export function hmacSha256(key, message) {
26	  const block = normalizeKey(key);
27	
28	  const inner = new Uint8Array(SHA256_BLOCK_SIZE + message.length);
29	  const outerPad = new Uint8Array(SHA256_BLOCK_SIZE);
30	  for (let i = 0; i < SHA256_BLOCK_SIZE; i++) {
31	    inner[i] = block[i] ^ 0x36;
32	    outerPad[i] = block[i] ^ 0x5c;
33	  }
34	  inner.set(message, SHA256_BLOCK_SIZE);
35	
36	  const innerDigest = sha256(inner);
37	
38	  const outer = new Uint8Array(SHA256_BLOCK_SIZE + innerDigest.length);
39	  outer.set(outerPad, 0);
40	  outer.set(innerDigest, SHA256_BLOCK_SIZE);
41	
42	  return sha256(outer);
