16	 * @param {string} str
17	 * @returns {Uint8Array}
18	 */
19	export function utf8Encode(str) {
20	  const out = [];
21	  for (let i = 0; i < str.length; i++) {
22	    let cp = str.charCodeAt(i);
23	
24	    if (cp >= 0xd800 && cp <= 0xdbff) {
25	      const next = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
26	      if (next >= 0xdc00 && next <= 0xdfff) {
27	        cp = (cp - 0xd800) * 0x400 + (next - 0xdc00) + 0x10000;
28	        i++;
29	      } else {
30	        cp = 0xfffd;
31	      }
32	    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
33	      cp = 0xfffd;
34	    }
35	
36	    if (cp < 0x80) {
37	      out.push(cp);
38	    } else if (cp < 0x800) {
39	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
40	    } else if (cp < 0x10000) {
41	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
42	    } else {
43	      out.push(
44	        0xf0 | (cp >> 18),
45	        0x80 | ((cp >> 12) & 0x3f),
46	        0x80 | ((cp >> 6) & 0x3f),
47	        0x80 | (cp & 0x3f),
48	      );
49	    }
50	  }
51	  return Uint8Array.from(out);
