63	  while (i < bytes.length) {
64	    const b0 = bytes[i];
65	    let cp;
66	    let width;
67	
68	    if (b0 < 0x80) {
69	      cp = b0;
70	      width = 1;
71	    } else if ((b0 & 0xe0) === 0xc0) {
72	      cp = b0 & 0x1f;
73	      width = 2;
74	    } else if ((b0 & 0xf0) === 0xe0) {
75	      cp = b0 & 0x0f;
76	      width = 3;
77	    } else if ((b0 & 0xf8) === 0xf0) {
78	      cp = b0 & 0x07;
79	      width = 4;
80	    } else {
81	      out += '�';
82	      i++;
83	      continue;
84	    }
85	
86	    if (i + width > bytes.length) {
87	      out += '�';
88	      i++;
89	      continue;
90	    }
91	
92	    let valid = true;
93	    for (let k = 1; k < width; k++) {
94	      const bk = bytes[i + k];
95	      if ((bk & 0xc0) !== 0x80) {
96	        valid = false;
97	        break;
98	      }
99	      cp = (cp << 6) | (bk & 0x3f);
