103	    const minimum = [0, 0, 0x80, 0x800, 0x10000][width];
104	    if (!valid || cp < minimum || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
105	      out += '�';
106	      i++;
107	      continue;
108	    }
109	
110	    out += String.fromCodePoint(cp);
111	    i += width;
112	  }
113	  return out;
114	}
