116	/**
117	 * Constant-space equality check over two byte arrays.
118	 *
119	 * @param {Uint8Array} a
120	 * @param {Uint8Array} b
121	 * @returns {boolean}
122	 */
123	export function bytesEqual(a, b) {
124	  if (a.length !== b.length) return false;
125	  let diff = 0;
126	  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
127	  return diff === 0;
