136	export function concatBytes(...chunks) {
137	  let total = 0;
138	  for (const c of chunks) total += c.length;
139	  const out = new Uint8Array(total);
140	  let offset = 0;
141	  for (const c of chunks) {
142	    out.set(c, offset);
143	    offset += c.length;
144	  }
145	  return out;
146	}
