5	const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
6	
7	const REVERSE = (() => {
8	  const table = new Int16Array(128).fill(-1);
9	  for (let i = 0; i < ALPHABET.length; i++) table[ALPHABET.charCodeAt(i)] = i;
10	  // Accept the standard alphabet too, so tokens produced elsewhere still decode.
11	  table['+'.charCodeAt(0)] = 62;
12	  table['/'.charCodeAt(0)] = 63;
13	  return table;
14	})();
