16	/**
17	 * @param {Uint8Array} bytes
18	 * @returns {string} base64url text with the `=` padding stripped
19	 */
20	export function b64urlEncode(bytes) {
21	  let out = '';
22	  let i = 0;
23	
24	  for (; i + 2 < bytes.length; i += 3) {
25	    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
26	    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63] + ALPHABET[n & 63];
27	  }
28	
29	  const rest = bytes.length - i;
30	  if (rest === 1) {
31	    const n = bytes[i] << 16;
32	    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63];
33	  } else if (rest === 2) {
34	    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
35	    out += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63];
36	  }
37	
38	  return out;
39	}
