41	/**
42	 * @param {string} text base64url text, with or without `=` padding
43	 * @returns {Uint8Array}
44	 * @throws {Error} on characters outside the alphabet or an impossible length
45	 */
46	export function b64urlDecode(text) {
47	  let clean = '';
48	  for (let i = 0; i < text.length; i++) {
49	    const ch = text[i];
50	    if (ch === '=') continue;
51	    const code = text.charCodeAt(i);
52	    if (code > 127 || REVERSE[code] === -1) {
53	      throw new Error(`Invalid base64url character: ${JSON.stringify(ch)}`);
54	    }
55	    clean += ch;
56	  }
57	
58	  if (clean.length % 4 === 1) throw new Error('Invalid base64url length');
59	
60	  const outLength = Math.floor((clean.length * 3) / 4);
61	  const out = new Uint8Array(outLength);
62	
63	  let acc = 0;
64	  let bits = 0;
65	  let pos = 0;
66	  for (let i = 0; i < clean.length; i++) {
67	    acc = (acc << 6) | REVERSE[clean.charCodeAt(i)];
68	    bits += 6;
69	    if (bits >= 8) {
70	      bits -= 8;
71	      out[pos++] = (acc >> bits) & 0xff;
72	    }
73	  }
74	
75	  return out;
76	}
